insert into public.question_banks (id, course_version_id, title)
values
  ('bfebb0e3-f689-5697-81e9-8f5e0a60d887', '4becab3e-b832-558c-9dec-b03f35848333', 'Técnicos de exterior 20 h · Bloque 1 · Definición de los trabajos'),
  ('54c78805-ffba-5765-8e97-7734ea2b25f8', '4becab3e-b832-558c-9dec-b03f35848333', 'Técnicos de exterior 20 h · Bloque 2 · Técnicas preventivas y de protección'),
  ('d009db8a-38d0-5c9b-ae18-4f809ed5455c', '4becab3e-b832-558c-9dec-b03f35848333', 'Técnicos de exterior 20 h · Bloque 3 · Equipos de trabajo, EPI y medios auxiliares'),
  ('87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '4becab3e-b832-558c-9dec-b03f35848333', 'Técnicos de exterior 20 h · Bloque 4 · Control y vigilancia del lugar de trabajo'),
  ('210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '4becab3e-b832-558c-9dec-b03f35848333', 'Técnicos de exterior 20 h · Bloque 5 · Interferencias con otras actividades'),
  ('b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '4becab3e-b832-558c-9dec-b03f35848333', 'Técnicos de exterior 20 h · Bloque 6 · Normativa y legislación')
insert into public.questions (id, question_bank_id, prompt, type, explanation, points, active, lesson_audio_segment_id)
values
  ('7293cef2-37f0-5ac1-86a3-cca288f22173', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Por qué debe analizarse el ciclo completo de una explotación exterior?', 'single_choice', 'La preparación, el arranque, la carga, el transporte, el tratamiento y el mantenimiento forman una cadena; evaluar una tarea aislada puede ocultar riesgos transmitidos entre fases.', 1, 'true', '3ba20ac5-543f-586d-96f8-088b0e5ee50a'),
  ('97b6b672-1fc1-5a8d-b2ea-1fa6bcc50752', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Dónde suelen aparecer riesgos que una evaluación aislada puede pasar por alto?', 'single_choice', 'Las interfaces entre preparación, arranque, carga, transporte y tratamiento merecen tanta atención como cada fase por separado.', 1, 'true', '11e37bba-6ba4-5add-96f0-acc874e0df29'),
  ('0bbda868-bce2-5aa2-bcb7-3e5571c3352d', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Cuál de estas descripciones permite evaluar correctamente una tarea?', 'single_choice', 'Una tarea debe quedar descrita con alcance, ubicación, participantes, equipos, energías, secuencia, duración, interferencias, parada y estado de entrega.', 1, 'true', 'd7e5880d-e929-58db-b274-a1dfd7973f51'),
  ('8da37636-373e-547c-b859-aee2af5a9353', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', 'Al analizar el cambio de un latiguillo, ¿qué conjunto debe considerarse?', 'single_choice', 'El análisis debe integrar personas, excavadora, bomba, implemento, presión residual, gravedad y cualquier otra energía o equipo relacionado.', 1, 'true', '27555c90-0e68-5bd7-ae45-a4e9d02c9dea'),
  ('1bcd7acb-ab52-5741-9a50-93b8ef624126', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Qué tres elementos forman el modelo que ayuda a comprender un escenario peligroso?', 'single_choice', 'Comprender de dónde procede la energía, qué trayectoria puede seguir y quién puede quedar expuesto permite seleccionar controles eficaces.', 1, 'true', 'd2fcf402-89a4-53bf-a9be-4e4b1c695247'),
  ('d8ab4548-f702-5aa0-aaaa-db41532d2d10', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', 'Producción quiere probar un triturador mientras una contrata trabaja aguas abajo. ¿Qué procede?', 'single_choice', 'Dos tareas correctas por separado pueden crear un riesgo nuevo al coincidir. La coordinación debe controlar la interacción real.', 1, 'true', '2511f687-9ff0-560e-b4b8-ee4349f09dd8'),
  ('d1f2756e-733d-52de-a1f4-441b33a65ce2', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Qué debe estar definido antes de comenzar una tarea respecto a una posible parada?', 'single_choice', 'Parar es eficaz cuando existen criterios observables, una actuación prevista y un camino claro y documentado para reanudar.', 1, 'true', '5b9376e9-85b8-51c5-8ca5-370744e9ab38'),
  ('fe62889d-1ab0-58c7-8b11-a3c3fa174690', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Qué debe hacerse antes de valorar el riesgo de una operación real?', 'single_choice', 'Primero se reconstruye el trabajo real; después se valora el riesgo y se seleccionan controles.', 1, 'true', '36722f07-6b52-5472-a35c-dd6fc38bd126'),
  ('5940e279-125c-5e59-8c61-8face35a36d4', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', 'Una ficha enumera personas y equipos, pero omite criterios de parada y autoridad de reanudación. ¿Es suficiente?', 'single_choice', 'Una ficha útil debe permitir decidir antes, durante y al finalizar la tarea, también cuando cambian las condiciones.', 1, 'true', '1a378471-5b60-5df1-bffc-caf3d4efb23e'),
  ('e2640ef0-0906-59cb-814a-3f871baa6b9b', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Qué aporta ordenar las fases y describir energía y trayectoria?', 'single_choice', 'La definición del trabajo es la base del análisis posterior y permite ver qué condiciones recibe cada equipo o fase.', 1, 'true', '29aa02c9-97c1-5893-a21a-52499f0c64d6'),
  ('d6256906-eb9c-5e75-80d0-b495e0f97ac5', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Cuál es la mejor formulación de un control?', 'single_choice', 'Un control debe ser observable y verificable. Las expresiones genéricas dependen de la conducta y no definen una condición de aceptación.', 1, 'true', null),
  ('e3c11a1e-b889-5180-ba4e-8b8f5dc1b7ec', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', 'Dos trabajos tienen procedimientos correctos, pero comparten una zona de maniobra. ¿Qué falta comprobar?', 'single_choice', 'La coordinación debe revisar la coincidencia real de trayectorias, tiempos, energías, accesos y comunicaciones.', 1, 'true', null),
  ('efc01335-907e-5cc1-a89e-4416a15ac178', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', 'Si cambia el equipo previsto para una tarea, ¿qué debe hacerse antes de continuar?', 'single_choice', 'Un cambio de equipo puede modificar geometría, alcance, energías, visibilidad e interferencias y debe reevaluarse antes de continuar.', 1, 'true', null),
  ('78d7ab25-d541-55da-bfa4-73103ecca602', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Qué evidencia permite cerrar correctamente una tarea?', 'single_choice', 'El cierre exige verificar el estado de entrega y las condiciones de seguridad, no solo que la intervención haya terminado.', 1, 'true', null),
  ('5f2e2471-4e72-5e9f-9c7b-fca8866c8f99', 'bfebb0e3-f689-5697-81e9-8f5e0a60d887', '¿Cuál es el orden preventivo correcto al preparar una operación?', 'single_choice', 'La evaluación de calidad parte del trabajo real y termina en controles verificables con responsables y criterios de aceptación.', 1, 'true', null),
  ('0dc3f60c-601a-5a0e-91ca-14d3e97a19be', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Qué limitación tiene una matriz numérica de riesgos?', 'single_choice', 'La cifra debe apoyarse en una descripción de peligro, trayectoria, exposición, controles, responsables y verificación.', 1, 'true', 'db7a3540-b88e-5bd7-8e63-14c40cad150f'),
  ('7ad04a6d-7d85-589f-89f0-a930f899e4b9', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿De qué depende la estabilidad de un talud además de su geometría?', 'single_choice', 'La estabilidad combina diseño, observación del terreno y revisión ante cambios; dos frentes con el mismo ángulo pueden comportarse de forma distinta.', 1, 'true', '3977a90e-7b89-5343-90f6-fa9c00c3b6ce'),
  ('58c481b3-dd85-54d1-9156-dec1380e41c2', '54c78805-ffba-5765-8e97-7734ea2b25f8', 'Ante grietas nuevas, caída de fragmentos o agua turbia en un frente, ¿cuál es la respuesta inicial?', 'single_choice', 'Los indicadores tempranos se tratan de forma conservadora; no se entra en una zona potencialmente inestable para confirmar el peligro.', 1, 'true', '5212d685-d476-59c7-b6a4-bd1ab5c61211'),
  ('e532a1ff-8d6c-54a2-8035-e061b360e326', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Cuándo debe escalarse una observación geotécnica?', 'single_choice', 'La inspección operativa, técnica y especializada tiene alcances distintos; cada nivel debe reconocer sus límites y escalar.', 1, 'true', '2715e41b-50fb-54b4-b163-cbd26f818de3'),
  ('ac6caef3-cf83-5a21-bd87-070e0e91e9c8', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Cómo debe gestionarse el agua en una explotación exterior?', 'single_choice', 'El agua puede afectar a estabilidad, erosión, visibilidad y frenado; el drenaje debe controlar todo su recorrido.', 1, 'true', '6194460d-6e87-518a-a1ab-9cf467ea059e'),
  ('a93b3532-a7f7-5377-ac54-391dbef8538f', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Por qué la geometría de una pista es una barrera técnica?', 'single_choice', 'La pista funciona como un sistema y debe comprobarse contra proyecto, ITC, vehículo crítico y estado real.', 1, 'true', '02de303f-099b-54c7-8d0f-dd21ea6374a7'),
  ('e7421e5d-42c4-5213-ac00-757a5199e243', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Cuál es el control prioritario en la interacción entre maquinaria móvil y personas?', 'single_choice', 'La separación elimina o reduce la exposición y es más robusta que depender solo de avisos o conducta.', 1, 'true', '958d9204-b715-5d74-89aa-4ae8306b28e6'),
  ('ba2710c7-493d-5112-bb50-2ac8631449ea', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Qué significa establecer contacto positivo antes de entrar en una zona de maniobra?', 'single_choice', 'Ver la máquina no demuestra que el operador haya visto a la persona; la confirmación debe ser clara y previa.', 1, 'true', '364a9daf-18b4-58d2-acaf-c74fdc086aa2'),
  ('fee85b14-f6a9-54f1-bbf8-efad8f65a0d6', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Qué implica la existencia de puntos ciegos en una máquina?', 'single_choice', 'Un avisador no convierte una zona ciega en segura; la limitación de diseño exige varias barreras coordinadas.', 1, 'true', 'c2be2216-c4b6-526c-9c2d-8a7ce22ae5e4'),
  ('80ea231f-ed35-557b-9cae-d5385ebf13b7', '54c78805-ffba-5765-8e97-7734ea2b25f8', 'Ante un barreno sospechoso o fallido, ¿qué debe hacerse?', 'single_choice', 'La duda se gestiona como barreno fallido hasta que personal habilitado determine y aplique la actuación correspondiente.', 1, 'true', '55456e1f-6069-54a8-bc42-1bc273df8253'),
  ('9c4981fa-a8c5-537b-86e9-9106ed4339eb', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Poner un mando a cero equivale a aislar un equipo?', 'single_choice', 'La detención no demuestra aislamiento. Deben identificarse y controlar todas las fuentes y energías acumuladas.', 1, 'true', 'c637e0fc-7dcc-5324-9cd8-2d7eb692d2b3'),
  ('6198707c-56d4-53f2-abae-565108888ce3', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Qué debe demostrarse antes de tocar un equipo consignado?', 'single_choice', 'La consignación incluye identificar, parar, aislar, bloquear, señalizar, disipar, verificar y controlar la restitución.', 1, 'true', '1c303a78-4bdb-5db5-9957-0e8f76234bf6'),
  ('1db0a54b-7f08-570c-a44e-5c4ee2d6ffc7', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Puede evaluarse la exposición a sílice observando si hay polvo visible?', 'single_choice', 'El polvo visible no representa toda la exposición a sílice cristalina respirable; deben utilizarse métodos adecuados de evaluación.', 1, 'true', '5f2da823-2c67-54a8-85aa-8135afb0735d'),
  ('9bed07f7-73ec-5689-a723-439fdb6c6d25', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Cuál es el orden correcto para controlar el polvo?', 'single_choice', 'La prioridad es evitar o reducir la generación y propagación; el EPI no compensa una captación averiada o una cabina con fugas.', 1, 'true', 'd8e00672-ba84-56ff-bf27-7d14153ddc86'),
  ('46a5be11-3431-5663-8977-436966ed337e', '54c78805-ffba-5765-8e97-7734ea2b25f8', '¿Cuál es la secuencia general ante una emergencia?', 'single_choice', 'La ayuda no debe crear una segunda víctima. Primero se protege, se activa la respuesta y se socorre dentro de las competencias y condiciones seguras.', 1, 'true', 'ac4a8dff-11f0-5a9a-8bc7-2e92c17079d4'),
  ('868ba427-9205-5c15-8d71-46f35784cc5a', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Cuándo debe revisarse la adecuación de un equipo a lo largo de su vida?', 'single_choice', 'La conformidad inicial no sustituye la gestión durante todo el ciclo de vida ni la revisión ante nuevas condiciones de uso.', 1, 'true', '86cfe71a-6481-55f2-9a55-7855bc882be1'),
  ('1c2e0795-a407-5a3e-8d72-a7ab23cc2ae1', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Qué enfoque permite comparar correctamente perforadora, excavadora y cargadora?', 'single_choice', 'Cada máquina combina geometría, movimientos, visibilidad, terreno y funciones diferentes; la evaluación debe reflejar el uso real.', 1, 'true', 'f2ebeebb-987d-5b61-8e40-8bc1b1abf6fe'),
  ('99aa226a-16d2-52c0-bad5-1dbad5cbb8ee', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Por qué una misma pista no presenta el mismo riesgo para un volquete, un bulldócer y una motoniveladora?', 'single_choice', 'La compatibilidad se analiza con el vehículo real y su función, no suponiendo que una pista sirve igual para todos.', 1, 'true', 'ca31f3c2-b504-5f27-a17a-1fedbb1f8794'),
  ('d063aac1-eef1-57f0-9def-e5d0519688c9', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Qué demuestra el riesgo conjunto de trituradoras, cintas y vehículos ligeros?', 'single_choice', 'Arranques remotos, material acumulado, transferencias y puntos ciegos conectan equipos que no deben analizarse de forma aislada.', 1, 'true', 'a9e157f0-0945-5f8f-a140-55371fd0f338'),
  ('6eee8c2c-74f2-5e44-b23b-096c634456f7', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Qué NO demuestra por sí solo el marcado CE?', 'single_choice', 'La adecuación al puesto y al uso real debe verificarse en la explotación, aunque el equipo disponga de marcado y documentación.', 1, 'true', '43d96e7e-5b47-5f9f-9fa4-4c8258605baf'),
  ('b2691d21-b669-5074-add2-9971e4226317', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Por qué ROPS y cinturón deben considerarse conjuntamente?', 'single_choice', 'ROPS sin cinturón no constituye un sistema completo; ambos elementos deben estar en condiciones y utilizarse correctamente.', 1, 'true', '293778b7-5d20-57b5-8956-d67c7b9f40fc'),
  ('192c3cbe-9f59-542a-9593-bd9f41eaab0d', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Cómo deben comprobarse frenos, dirección, visibilidad y avisadores?', 'single_choice', 'Las funciones críticas se prueban en condiciones controladas y se comparan con criterios definidos; la ausencia de aviso no prueba su eficacia.', 1, 'true', 'ee0be948-1485-5caf-83f6-1ebe01f9d69c'),
  ('00bdc6a3-21cc-5879-bfec-4d92b8fbd459', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Puede utilizarse una parada de emergencia como aislamiento habitual para intervenir?', 'single_choice', 'La parada de emergencia no controla todas las energías ni impide necesariamente un rearme; para intervenir se requiere consignación.', 1, 'true', 'b490ba11-90f5-581e-a4a3-105900639f7d'),
  ('ddf2e1c2-69a3-54af-99fb-2821f8941ebc', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Qué ventaja aporta un recorrido sistemático de inspección antes del uso?', 'single_choice', 'Una secuencia estable desde el entorno hasta las funciones ayuda a detectar y clasificar defectos sin dejar zonas sin revisar.', 1, 'true', '8e039783-2397-541a-ba18-f9e32a6e9d09'),
  ('05ab38b3-91c2-5a9e-b8e1-44d1ba2bbbf9', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', 'Si no se conoce la consecuencia de un defecto, ¿cómo debe clasificarse?', 'single_choice', 'Un defecto no se rebaja por intuición. Debe relacionarse con la función afectada y la consecuencia posible.', 1, 'true', '213f7fe8-95cb-5d26-8480-6ce539589e94'),
  ('995ec004-9732-5a28-8368-dccedd617e5a', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', 'Antes de abrir una conexión con fluido a presión, ¿qué debe hacerse?', 'single_choice', 'La intervención segura comienza antes de abrir protecciones o conexiones y controla también energías residuales y gravedad.', 1, 'true', '5c31b4d9-b311-5004-8a60-5ffd37e0c880'),
  ('f43778a8-5868-519f-947b-3c9904ffdf22', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Qué lugar ocupa el EPI en la jerarquía de controles?', 'single_choice', 'El EPI protege frente al riesgo residual y debe seleccionarse, ajustarse, mantenerse y comprobarse sin sustituir medidas más robustas.', 1, 'true', 'f75616eb-fde2-50b5-b619-0bdef19067f2'),
  ('aced3d5b-5f5a-54f6-9942-398d814bd0d4', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', '¿Cuándo puede justificarse una escalera como puesto de trabajo?', 'single_choice', 'El medio de acceso se elige por riesgo, duración y condiciones de la tarea; andamios o plataformas pueden ser necesarios.', 1, 'true', 'd8094197-e993-548a-95cf-9221e73e6fa8'),
  ('531389bb-bf9c-505e-a819-6f6f1c0fc725', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', 'Antes de un izado, ¿qué conjunto debe conocerse?', 'single_choice', 'Un accesorio certificado puede fallar si se emplea en una configuración o ángulo no previsto; nadie debe situarse bajo la carga.', 1, 'true', '31505e2d-9ae8-5663-9946-948ed7336cb0'),
  ('16e8147c-e704-5d8e-960f-abe734318d8d', 'd009db8a-38d0-5c9b-ae18-4f809ed5455c', 'Un volquete pierde la cámara necesaria para una maniobra con visibilidad crítica. ¿Qué procede?', 'single_choice', 'La producción no convierte un defecto crítico en aceptable y una alarma no sustituye una función de visibilidad necesaria.', 1, 'true', '01e9e8a4-6e08-5490-91b8-2f16d37e4469'),
  ('f45376e4-97a8-51d5-b013-2b5cab13f86a', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué diferencia una vigilancia eficaz de una ronda de observación?', 'single_choice', 'Vigilar implica comparar con un estándar, detectar cambios, decidir, actuar y comprobar que la condición se ha recuperado.', 1, 'true', 'c87642d4-60f7-5533-a95c-356ede29becb'),
  ('a7c52d4f-24e2-5cf5-a0e5-6be21d832b8a', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué puede exigir una inspección extraordinaria aunque ya se haya hecho la ronda prevista?', 'single_choice', 'La frecuencia fija no sustituye las inspecciones activadas por eventos que pueden modificar el riesgo.', 1, 'true', '1f9a3785-f0e5-538c-9c74-bd905bbf8ba6'),
  ('cd10d4d8-b270-5772-8391-342380de6dda', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Cuándo se considera cerrada una inspección?', 'single_choice', 'El cierre es técnico y requiere verificación del resultado, no solo completar una acción administrativa.', 1, 'true', 'db3cdac1-9a47-52b8-ae65-2a05353a9938'),
  ('d4aeb1b0-413f-543e-9b69-ae2712d8f189', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué debe incluir el registro de una desviación?', 'single_choice', 'Sin criterio de cierre, una acción puede figurar como terminada y seguir abierta desde el punto de vista técnico.', 1, 'true', '1e8f1419-73a8-543f-9898-a07eeba5e7bf'),
  ('9fc0a4f8-7c38-50b7-b71c-a8eae949da42', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué caracteriza un estado de alarma frente a uno de alerta?', 'single_choice', 'Los umbrales y respuestas deben acordarse con antelación para evitar que la presión productiva modifique la decisión.', 1, 'true', '7a7c25bf-1e8c-5f94-9e2a-b248f656e479'),
  ('035ffaf4-3f0a-5408-9020-d3a4a5a4ee1e', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Cómo debe tratar la organización una parada preventiva justificada?', 'single_choice', 'Quien detecta una condición peligrosa debe poder dejar el equipo seguro, controlar la zona, comunicar y recibir respuesta sin represalias.', 1, 'true', '84849edd-dc2f-5f6a-ab0a-195218d9c127'),
  ('35fd422f-2163-597a-bfa9-6645fcf02f4a', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué se necesita para reabrir una zona después de una parada?', 'single_choice', 'La reapertura debe apoyarse en evidencia proporcional a la criticidad y en una decisión de la persona autorizada.', 1, 'true', '19315d71-30bc-5e2b-ac87-2b546be2b745'),
  ('4d8f185e-0a19-5df7-a0e1-606c29a8ef5a', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', 'Un bache reaparece después de tres reparaciones. ¿Qué debe hacerse?', 'single_choice', 'La recurrencia indica que no se ha tratado la causa, que puede estar en drenaje, base, pendiente, carga o método.', 1, 'true', '6ee0c8dc-150f-50d5-bcfa-88854aa9d5f5'),
  ('9c45f731-240b-5812-bee3-32fe690f917a', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Cuál es el orden preventivo ante una alarma crítica?', 'single_choice', 'La respuesta conserva el orden preventivo y evita recuperar producción antes de demostrar una condición segura.', 1, 'true', 'f6507ea1-3a05-56b6-a05b-dbff19c41ac3'),
  ('a7adde1e-de1e-54ba-8301-aad9d8a84194', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Por qué una reparación repetida no equivale a cerrar una desviación?', 'single_choice', 'La eficacia se verifica observando la función recuperada y el comportamiento posterior, no contando intervenciones.', 1, 'true', '0952ca1e-0397-5442-8987-b13b7481c005'),
  ('1a8405e8-d3e9-5385-b922-6272cc5cdba3', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', 'Una fotografía muestra una cuneta limpia. ¿Es evidencia suficiente para cerrar el problema de drenaje?', 'single_choice', 'La evidencia debe corresponder al criterio de cierre y demostrar la función, no solo la apariencia de la acción.', 1, 'true', null),
  ('b07c67da-9c19-5c1d-90a3-800f581eecb1', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Cuándo deben definirse los umbrales de alerta y alarma?', 'single_choice', 'Definirlos previamente protege la decisión frente a improvisación y presión operativa.', 1, 'true', null),
  ('b33b4573-694f-5bf7-ad17-3f1a59c23e72', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué debe hacer primero quien detecta una pérdida de una barrera crítica?', 'single_choice', 'La prioridad es controlar la exposición; después se analiza la causa y se definen las condiciones de reapertura.', 1, 'true', null),
  ('57f184ec-bd97-51b9-b62b-23bb73dc9a39', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Qué hace que una frecuencia de inspección sea adecuada?', 'single_choice', 'La frecuencia debe permitir detectar el deterioro antes de una exposición inaceptable y complementarse con inspecciones por eventos.', 1, 'true', null),
  ('68e4e0b3-65bd-5d29-8c57-fd7508ad474e', '87e8f0d2-413c-5dae-bf1e-9c7370aadea2', '¿Quién debe poder autorizar una reapertura?', 'single_choice', 'La autoridad de reanudación debe estar prevista y apoyarse en verificación proporcional a la criticidad.', 1, 'true', null),
  ('6ecbb108-24e1-5cea-b031-fb0b201aa665', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Cuándo aparece un riesgo emergente por interferencia?', 'single_choice', 'La coincidencia puede introducir nuevas exposiciones en espacio, tiempo, energía, información, acceso o emergencia.', 1, 'true', 'afe655d9-f671-5942-919c-898bbd47402e'),
  ('27edeeb7-4a70-5111-8ae8-74bfa4d4111a', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Qué dimensiones debe revisar una coordinación completa?', 'single_choice', 'Las interferencias no son solo espaciales; también pueden afectar pruebas, alarmas, rutas, energías o comunicaciones.', 1, 'true', '77988056-e38f-56f8-84c9-751dff663d59'),
  ('af2a3ed2-3efe-54e9-922a-7d5b3d899120', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Qué efecto tiene la coordinación de actividades sobre las responsabilidades propias de cada empresa?', 'single_choice', 'La titular, las concurrentes y la principal conservan las obligaciones que les corresponden; coordinar no significa trasladarlas.', 1, 'true', '27ccc789-98f0-5e63-9fac-b95522cb18e1'),
  ('25ef65bb-246e-54d0-9fe4-8e9f9aae776c', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Cuándo debe realizarse la coordinación?', 'single_choice', 'La coordinación es continua: define interfaces, comprueba requisitos, revisa la realidad, supervisa cambios y asegura una entrega segura.', 1, 'true', 'b8c19953-22bc-596a-9671-5aba95a551e5'),
  ('03420a39-a608-5322-aa87-c1ed54071440', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Cómo termina una reunión previa eficaz?', 'single_choice', 'La reunión debe modificar y concretar el trabajo, no limitarse a demostrar que se celebró.', 1, 'true', '8f12885f-4d9f-5cdb-9b25-4114919f897a'),
  ('7ed02f8d-8290-5343-8c7b-0ab2f4c337f5', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', 'En una consignación compartida, ¿puede retirarse el bloqueo de otra persona?', 'single_choice', 'La custodia personal del bloqueo y los cambios de turno deben estar definidos; una retirada excepcional exige el procedimiento autorizado.', 1, 'true', '4ef961cb-7e12-5cbe-b0e2-c6d76a25375b'),
  ('a47581fe-5ed6-5010-8794-a5d151a6a317', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Cómo deben gestionarse interferencias previsibles como voladura con topografía o producción con mantenimiento?', 'single_choice', 'Lo previsible debe resolverse en la planificación y reflejarse en controles de campo verificables.', 1, 'true', 'f9c0f6f2-97cb-5528-8615-65e6c795a8ad'),
  ('8861624d-7615-53fd-b5ef-b318287a21fa', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Qué debe ser compatible entre empresas para responder a una emergencia?', 'single_choice', 'Todas las personas deben reconocer la alarma, aparecer en el recuento y permitir que los servicios externos accedan con coordenadas y guía.', 1, 'true', 'a07ce8c2-f6b0-5d27-85e2-b19e96fe87f9'),
  ('b38c4f59-9a4c-59a9-a8ca-c714f6df54a8', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', 'Una contrata bloquea el motor local de una cinta y producción quiere probar el triturador aguas arriba. ¿Qué procede?', 'single_choice', 'La prueba no comienza hasta confirmar que nadie permanece expuesto y que todas las fuentes y bloqueos se gestionan conjuntamente.', 1, 'true', 'f3740480-cb96-5358-9d76-e9f30126eafe'),
  ('2b2765b9-95cd-5ae9-b56e-885ff53f6bd5', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', 'Dos empresas utilizan alarmas distintas en el mismo sector. ¿Qué revela esta situación?', 'single_choice', 'La coordinación debe garantizar que toda persona reconoce la alarma y sabe cómo evacuar y ser contabilizada.', 1, 'true', 'ac678c18-b936-553c-a02d-e34ee7d55ac3'),
  ('dd6bd3f6-ca15-5bec-9c23-f2b47d24fc7d', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', 'Topografía necesita entrar en una zona activa de carga. ¿Cuál es el control correcto?', 'single_choice', 'La entrada debe eliminar la coincidencia de trayectorias y quedar coordinada con autorización y comunicación inequívocas.', 1, 'true', null),
  ('1adec334-05a5-50bb-999d-39f725decf21', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Qué debe ocurrir cuando cambia el alcance de una contrata durante el trabajo?', 'single_choice', 'La coordinación es continua y debe responder a cambios que modifiquen la exposición o las responsabilidades operativas.', 1, 'true', null),
  ('5d73ed7c-8642-5c9e-a665-95b91204ed81', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Qué hace verificable un acuerdo de coordinación?', 'single_choice', 'Los acuerdos deben convertirse en decisiones observables con responsables, referencias físicas, comunicaciones y criterios de cambio.', 1, 'true', null),
  ('fc2bb5a1-22c9-5f27-a2ab-def780d056a4', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', '¿Cuál es una señal de que la coordinación ha sido solo documental?', 'single_choice', 'La coordinación real modifica el trabajo y deja claras energías, autoridades, límites y comunicaciones.', 1, 'true', null),
  ('a468bcdf-a2ad-5ec5-8a67-2fb8b1de3103', '210b45cd-7030-5f19-a1ab-fb2f4767dfd5', 'Al terminar una intervención de una contrata, ¿qué debe incluir la entrega final?', 'single_choice', 'La coordinación continúa hasta que el sistema se entrega en condiciones conocidas y verificadas para su uso posterior.', 1, 'true', null),
  ('516c803d-2d05-5836-a6cd-24077cdfafed', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué significa conocer la normativa aplicable a una decisión técnica?', 'single_choice', 'El conocimiento normativo es operativo: conecta cada referencia con su ámbito, una obligación y una evidencia de cumplimiento.', 1, 'true', 'b9ff68aa-85b7-572d-970f-e36c12814c8f'),
  ('7d9998ca-b7d6-5a06-87e8-4f73b5ec60f2', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué disposiciones sitúan y estructuran la formación de técnicos titulados de exterior del grupo 5.2.a?', 'single_choice', 'La ITC 02.1.02 regula la formación preventiva y la ET 2003-1-10 fija para este grupo la duración y distribución de contenidos.', 1, 'true', 'c971a2f3-490a-53bb-b481-8dcf4da16065'),
  ('5795a37f-8d47-5c73-89e2-d52cc59e7af5', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Cuáles son los requisitos indicados para esta formación y su reciclaje?', 'single_choice', 'Para técnicos titulados de exterior, la formación regulada es presencial; la plataforma sirve de apoyo, preparación y repaso.', 1, 'true', '56b80ad0-7dbf-5401-a185-84998769fe70'),
  ('b172a215-d43f-5dca-9bf1-bb909dc338ca', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', 'Si una costumbre de la explotación contradice un límite vigente de una ITC, ¿qué prevalece?', 'single_choice', 'Las prácticas locales no pueden reducir una exigencia vigente; deben revisarse proyecto, ITC y condiciones aplicables.', 1, 'true', 'a869ad2f-6481-5c9a-8882-36b4770d0895'),
  ('b92ca55c-ed31-5e73-83a2-2a1879bdd562', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Quién tiene la obligación de evaluar, planificar e integrar la prevención?', 'single_choice', 'La prevención es una responsabilidad organizada de la empresa; el servicio preventivo asesora, pero no sustituye la gestión.', 1, 'true', '135b4d04-a137-586b-9d76-90689371fe66'),
  ('d38fac5f-765d-5840-be09-0efa41af3ed1', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué relación normativa es correcta?', 'single_choice', 'Una misma tarea puede activar simultáneamente requisitos sobre adecuación del equipo, protección personal y concurrencia de empresas.', 1, 'true', '2d1d58ed-0e48-543e-bf56-853f058d8709'),
  ('1256194a-7348-5156-97af-ab119ceb1bac', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué debe representar una medición de polvo, sílice, ruido o vibraciones?', 'single_choice', 'Cada agente tiene métodos, criterios y medidas específicos; no se presume cumplimiento sin una evaluación representativa.', 1, 'true', '5e7c2aa4-10c6-5211-99df-bde7e5f2d725'),
  ('2971cafb-1836-5cbb-ad08-3abfe2c6f589', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué habilitación aporta este curso para manipular explosivos o realizar trabajos eléctricos reservados?', 'single_choice', 'La formación preventiva general no amplía competencias legales. El técnico puede coordinar y verificar condiciones dentro de sus funciones.', 1, 'true', '0c468617-07f1-5cef-9427-023d3f609a23'),
  ('639a076d-3b43-58de-95ac-9da65118f93b', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué diferencia esencial existe entre una norma jurídica y una NTP?', 'single_choice', 'No debe presentarse una recomendación como obligación literal sin comprobar su fuente, ámbito e incorporación aplicable.', 1, 'true', '07b43318-3976-5659-96bf-40241dca6b07'),
  ('4bdee3c6-c16c-5ea3-a2d7-bc71285b8c82', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Cuál es la secuencia correcta de revisión normativa?', 'single_choice', 'La revisión debe ser trazable y alcanzar proyecto, DSS, disposiciones internas, formación, equipos y mediciones.', 1, 'true', '280a72ac-8d61-506e-9d6e-bfbccbb48b36'),
  ('9aba220d-39b0-5ba7-a21c-cdcc05ae4fa2', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué papel tienen los audios, diapositivas y pruebas de InmínerCampus en esta formación reglada?', 'single_choice', 'El diseño digital debe integrarse en una impartición presencial documentada conforme al sistema aplicable.', 1, 'true', null),
  ('83803e0b-50b7-5e3b-87f0-69a406b1fa7f', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', 'Para comprobar la anchura exigible de una pista, ¿qué debe hacerse?', 'single_choice', 'La decisión combina normativa minera, condiciones de la autoridad, proyecto y características reales de la explotación.', 1, 'true', null),
  ('4f9d4d86-6a10-575c-b4cf-c4e7d8cf5e0c', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', 'Si cambia un proceso y afecta a la evaluación, ¿qué documentación debe revisarse?', 'single_choice', 'El impacto normativo y preventivo debe trasladarse a todos los documentos y controles afectados antes de consolidar el cambio.', 1, 'true', null),
  ('0067faa8-b9e4-5b7a-be21-27632e9e51c9', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué fuente debe vigilarse para mantener actualizado el marco aplicable?', 'single_choice', 'La vigilancia utiliza fuentes oficiales y conserva enlace, versión, responsable y fecha para asegurar trazabilidad.', 1, 'true', null),
  ('2e48003e-3bcf-599e-bfce-ea3bd29ea9c5', 'b968bc7a-2c18-5b3c-aea5-ca806c1ed01b', '¿Qué debe hacerse con una versión normativa o instrucción que ha quedado obsoleta?', 'single_choice', 'El control documental evita el uso de versiones obsoletas sin perder la trazabilidad o el archivo exigible.', 1, 'true', null)
