values
  ('a38fa44b-9caa-541f-bcd8-59a16863bcf5', '7293cef2-37f0-5ac1-86a3-cca288f22173', 1, 'Porque las fases están relacionadas y una condición de una etapa puede afectar a las siguientes', 'true'),
  ('01a8169f-2c5d-5bbd-be76-231f9f5518e8', '7293cef2-37f0-5ac1-86a3-cca288f22173', 2, 'Porque todas las tareas utilizan la misma maquinaria', 'false'),
  ('72da909e-74f5-5ea8-9b01-351872ef053c', '7293cef2-37f0-5ac1-86a3-cca288f22173', 3, 'Porque elimina la necesidad de evaluar cada puesto', 'false'),
  ('dcbba003-d09b-5b17-8a69-ca6729ba23e8', '7293cef2-37f0-5ac1-86a3-cca288f22173', 4, 'Porque solo importa la fase con mayor producción', 'false'),
  ('75627847-e095-5422-aff6-eb56bd6b7e31', '97b6b672-1fc1-5a8d-b2ea-1fa6bcc50752', 1, 'En las interfaces entre fases y tareas', 'true'),
  ('bb2d2e70-c26f-5284-b561-5c0da6a27105', '97b6b672-1fc1-5a8d-b2ea-1fa6bcc50752', 2, 'Solo en las oficinas', 'false'),
  ('7be69b1e-3084-5ccd-9a84-9fa3407ee9ef', '97b6b672-1fc1-5a8d-b2ea-1fa6bcc50752', 3, 'Únicamente al terminar el turno', 'false'),
  ('b9d2ed6e-9ece-5d66-8cf6-cbfb39afc335', '97b6b672-1fc1-5a8d-b2ea-1fa6bcc50752', 4, 'Exclusivamente en equipos nuevos', 'false'),
  ('78699e18-e016-5b14-bbb6-6ecb183db027', '0bbda868-bce2-5aa2-bcb7-3e5571c3352d', 1, 'Mantenimiento de cinta', 'false'),
  ('67d76843-35d9-5133-8d1b-d2585689e79a', '0bbda868-bce2-5aa2-bcb7-3e5571c3352d', 2, 'Trabajo habitual con cuidado', 'false'),
  ('227ba3d0-370b-546e-b5a2-b077f76007df', '0bbda868-bce2-5aa2-bcb7-3e5571c3352d', 3, 'Intervención en un tramo identificado, con personas, energías, secuencia, interferencias y criterios de parada definidos', 'true'),
  ('fda8eec7-926e-5d40-90e3-bbfcecfa50e9', '0bbda868-bce2-5aa2-bcb7-3e5571c3352d', 4, 'Reparación rápida a decidir sobre la marcha', 'false'),
  ('9dd13e1d-f191-5f23-a645-ab2884702b74', '8da37636-373e-547c-b859-aee2af5a9353', 1, 'Solo la persona que realiza el cambio', 'false'),
  ('1ca91b52-7a6e-55c4-b921-740a7dc8921a', '8da37636-373e-547c-b859-aee2af5a9353', 2, 'Personas, equipos y todas las energías presentes', 'true'),
  ('e584531b-6628-5bb7-8092-ad2b69aaeffe', '8da37636-373e-547c-b859-aee2af5a9353', 3, 'Solo la presión indicada por el manómetro', 'false'),
  ('9c3e005e-7d62-599d-b72c-5754d7475884', '8da37636-373e-547c-b859-aee2af5a9353', 4, 'Únicamente las herramientas manuales', 'false'),
  ('9dbaa1b7-c3c2-5b46-a02d-6c055ac676a6', '1bcd7acb-ab52-5741-9a50-93b8ef624126', 1, 'Coste, plazo y producción', 'false'),
  ('894002d5-e534-5690-be72-a627cb296593', '1bcd7acb-ab52-5741-9a50-93b8ef624126', 2, 'Energía, trayectoria y persona expuesta', 'true'),
  ('6fe38167-0fdd-594b-a054-e1eafd7bafc7', '1bcd7acb-ab52-5741-9a50-93b8ef624126', 3, 'Norma, firma y archivo', 'false'),
  ('949e5ff3-dc93-5c4e-94ea-05e312444c17', '1bcd7acb-ab52-5741-9a50-93b8ef624126', 4, 'Equipo, marca y antigüedad', 'false'),
  ('571059c4-0491-5978-b88e-9c574bdb9fec', 'd8ab4548-f702-5aa0-aaaa-db41532d2d10', 1, 'Aplicar cada procedimiento por separado sin más coordinación', 'false'),
  ('39b8cf3f-cfb1-55f4-9e11-01cde4a8c30a', 'd8ab4548-f702-5aa0-aaaa-db41532d2d10', 2, 'Coordinar la interacción y evitar introducir energía en la zona ocupada', 'true'),
  ('5dc2939c-3dbe-5637-a008-f449726c5a09', 'd8ab4548-f702-5aa0-aaaa-db41532d2d10', 3, 'Avisar por radio después de arrancar', 'false'),
  ('144fddf0-44b9-50ce-ac42-829ab4a09cc5', 'd8ab4548-f702-5aa0-aaaa-db41532d2d10', 4, 'Confiar en que la contrata oirá el equipo', 'false'),
  ('6b8f9a57-8e28-562e-a060-73cd1e0c5118', 'd1f2756e-733d-52de-a1f4-441b33a65ce2', 1, 'Solo quién redactará el informe final', 'false'),
  ('8ec773a2-f397-55f8-b5c3-4addb93be7a7', 'd1f2756e-733d-52de-a1f4-441b33a65ce2', 2, 'La señal de parada, la respuesta inmediata, la evidencia exigida y quién puede autorizar la reanudación', 'true'),
